return {api_version=1,id="OG_310",name="Steward of Darkshire",text="Whenever you summon a 1-Health minion, give it <b>Divine Shield</b>.",set="OG",type="minion",class="paladin",rarity="rare",cost=3,attack=4,health=3,triggers={{event="minion_summoned",timing="after",active_zones={"board"},condition=function(ctx,self,event)return event.player==ctx:controller(self) and event.entity~=self and ctx:entity(event.entity).max_health==1 end,effect=function(ctx,self,event)cardlib.effects.grant_keyword(ctx, event.entity,"divine_shield")end}}}
